from collections import deque

def balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)  # push
        elif ch in pairs:
            if not stack:
                return False
            if stack.pop() != pairs[ch]:
                return False
    return not stack   # leftovers: unclosed

