class TreeNode:
    def __init__(self, key):
        self.key = key
        self.left = self.right = None

def insert(node, key):
    if node is None:
        return TreeNode(key)
    if key < node.key:
        node.left = insert(node.left, key)
    else:
        node.right = insert(node.right, key)
    return node

def in_order(node, out):
    if node:
        in_order(node.left, out)
        out.append(node.key)
        in_order(node.right, out)
    return out

